@contextmanager
def private_native_logs():
    """Suppress this thread's SDK/auth HTTP DEBUG records; restore all filters."""
    owner = threading.get_ident()
    prefixes = ('azure', 'msal', 'msal_extensions', 'urllib3', 'requests', 'http.client')
    def native(name):
        return any(name == p or name.startswith(p + '.') for p in prefixes)
    for name in ('azure.identity', 'azure.core.pipeline.policies.http_logging_policy', 'msal', 'urllib3.connectionpool'):
        logging.getLogger(name)
    loggers = [logging.getLogger(n) for n in list(logging.root.manager.loggerDict) if native(n)]
    handlers = set(logging.getLogger().handlers)
    for logger in loggers:
        handlers.update(logger.handlers)
    class Guard(logging.Filter):
        def filter(self, record):
            return threading.get_ident() != owner or not native(record.name)
    guard = Guard()
    for obj in [*loggers, *handlers]:
        obj.addFilter(guard)
    try:
        yield
    finally:
        for obj in [*loggers, *handlers]:
            obj.removeFilter(guard)

def _presence(value):
    if value is None:
        return 'absent'
    if not value.strip():
        return 'empty'
    if value.lstrip().casefold().startswith('@microsoft.keyvault'):
        return 'reference'
    if value.strip().casefold() in ('[redacted]', '<redacted>', 'redacted') or set(value.strip()) <= {'*'}:
        return 'masked'
    return 'literal'

def _site(data, target):
    if (not isinstance(data.get('id'), str) or data['id'].casefold() != target.casefold()
            or str(data.get('type', '')).casefold() != 'microsoft.web/sites'
            or not isinstance(data.get('name'), str) or data['name'].casefold() != target.rsplit('/', 1)[1].casefold()
            or not isinstance(data.get('properties'), dict) or not isinstance(data.get('kind'), str)):
        raise Incomplete('site_unbound')
    kinds = [v.strip().casefold() for v in data['kind'].split(',')]
    if not kinds or any(not re.fullmatch('[a-z0-9-]+', k) for k in kinds) or len(set(kinds)) != len(kinds):
        raise Incomplete('site_kind')
    if 'functionapp' not in kinds:
        return {'hosting': 'not_function'}
    if 'workflowapp' in kinds:
        return {'hosting': 'not_function'}
    if set(kinds) - {'functionapp', 'linux', 'container'}:
        return {'hosting': 'unsupported'}
    p = data['properties']
    config = p.get('siteConfig')
    flex = p.get('functionAppConfig')
    container = 'container' in kinds
    if config is not None and not isinstance(config, dict):
        raise Incomplete('site_config')
    for key in ('linuxFxVersion', 'windowsFxVersion'):
        value = config.get(key) if isinstance(config, dict) else None
        if value is not None and not isinstance(value, str):
            raise Incomplete('site_config')
        relevant = 'linuxFxVersion' if 'linux' in kinds else 'windowsFxVersion'
        if key == relevant and isinstance(value, str) and value.upper().startswith('DOCKER|'):
            container = True
    if flex is not None:
        if (not isinstance(flex, dict) or not isinstance(flex.get('runtime'), dict)
                or flex['runtime'].get('name') not in ('dotnet-isolated', 'node', 'java', 'powershell', 'python')
                or not isinstance(flex['runtime'].get('version'), str) or not flex['runtime']['version']
                or container):
            raise Incomplete('flex_config')
        return {'hosting': 'flex'}
    if container:
        return {'hosting': 'container'}
    # Missing full native site config cannot rule out a custom image. A null
    # field is not replaced with a synthetic classic-hosting declaration.
    if not isinstance(config, dict) or type(p.get('reserved')) is not bool or ('linux' in kinds) != p['reserved']:
        return {'hosting': 'unresolved'}
    field = 'linuxFxVersion' if p['reserved'] else 'windowsFxVersion'
    if not isinstance(config.get(field), str):
        return {'hosting': 'unresolved'}
    if p['reserved'] and not re.fullmatch(r'(?:PYTHON|NODE|JAVA|DOTNET|DOTNET-ISOLATED|POWERSHELL)\|[A-Za-z0-9._-]+', config[field], re.I):
        return {'hosting': 'unresolved'}
    return {'hosting': 'classic'}

def collect(reader, transport, scopes, wanted, options, *, named_checks,
            credential_context_id=None, customer_context_id=None):
    targets, selected = preflight(options, scopes, named_checks)
    if KIND not in wanted or not targets:
        return
    transport_capture = getattr(transport, 'ai_context_id', None)
    capture = transport_capture if credential_context_id is None else credential_context_id
    if (not isinstance(transport_capture, str) or not re.fullmatch('[0-9a-f]{32}', transport_capture)
            or not isinstance(capture, str) or not re.fullmatch('[0-9a-f]{32}', capture)
            or credential_context_id is not None and customer_context_id != 'scan-local:' + capture
            or credential_context_id is None and customer_context_id is not None):
        raise Incomplete('capture_unavailable')
    metadata = {KIND + '_authorized': True, KIND + '_checks': selected,
        KIND + '_capture': capture, KIND + '_selection': {
            scope: [identity(t) for t in targets if _RESOURCE.fullmatch(t)[1].casefold() == scope.casefold()] for scope in scopes},
        KIND + '_receipts': []}
    reader.function_declaration_metadata = metadata
    state = {'capture': capture, 'tenant': None, 'deadline': time.monotonic() + MAX_SECONDS, 'bytes': 0, 'calls': 0}
    receipts = metadata[KIND + '_receipts']
    for scope in scopes:
        names = [t for t in targets if _RESOURCE.fullmatch(t)[1].casefold() == scope.casefold()]
        if not names: continue
        def fetch(names=names, scope=scope):
            rows = []
            for target in names:
                ident = identity(target); start = len(receipts)
                marker = {'schema': SCHEMA, 'identity': ident, 'scope': scope, 'capture': capture,
                    'complete': False, 'hosting': 'unresolved', 'declarations': None, 'source_requests': []}
                try:
                    reader.call(_read, reader, transport, target, scope, 'subscription', state, receipts)
                    facts = reader.call(_read, reader, transport, target, scope, 'site', state, receipts)
                    marker.update(facts)
                    if facts['hosting'] not in ('not_function', 'unsupported') and (TELEMETRY in selected or facts['hosting'] == 'classic'):
                        marker['declarations'] = reader.call(_read, reader, transport, target, scope, 'settings', state, receipts)
                    marker['complete'] = True
                except Exception:
                    marker.update(complete=False, declarations=None)
                marker['source_requests'] = [r['id'] for r in receipts[start:]]
                rows.append({'id': ident, MARKER: marker, '_provenance': {'scope': scope,
                    'capture': capture, 'tenant_id': state['tenant'], 'source_requests': list(marker['source_requests'])}})
            yield rows
        reader.run([(KIND, scope, 'Microsoft.Web', fetch)])
    metadata[KIND + '_tenant'] = state['tenant']

def collect_proposal(connector, named_checks, *, credential=None):
    """Unregistered testable entrypoint; future root hooks must preserve gating."""
    from .azure import AzureTransport, _Reader
    from peaso.snapshot import make_snapshot
    options, scopes = connector.get('options', {}), connector.get('scopes', [])
    targets, selected = preflight(options, scopes, named_checks)
    if not targets:
        return make_snapshot('azure', scopes, [], metadata={'collection': 'read-only'})
    from peaso.checks.azure_function_settings_admission_20261020 import validate_proposal
    validate_proposal()
    reader = _Reader({**options, 'concurrency': 1, 'retries': 0})
    transport = None
    try:
        with private_native_logs():
            try:
                transport = AzureTransport(connector.get('auth', {}), credential=credential)
            except Exception:
                for scope in scopes:
                    reader.unavailable(KIND, scope, 'Microsoft.Web', Incomplete('credential_unavailable'))
        if transport is None:
            return final_snapshot(reader, make_snapshot('azure', scopes, reader.collections, metadata=reader.metadata()))
        collect(reader, transport, scopes, [KIND], options, named_checks=list(selected))
        return final_snapshot(reader, make_snapshot('azure', scopes, reader.collections, metadata=reader.metadata()))
    finally:
        if transport is not None:
            transport.tokens.clear()
            with private_native_logs():
                try: transport.close()
                except Exception: pass

def _evaluate(item, index, check):
    try:
        marker = _bound(item, index, check)
        hosting, settings = marker['hosting'], marker['declarations']
        if hosting == 'not_function':
            return 'NOT_APPLICABLE', {'observed': 'The selected native site is not a Function app.'}
        if check == source.RUNTIME:
            if hosting in ('container','flex'):
                text = ('Flex Consumption manages the host update setting through the platform.' if hosting == 'flex'
                        else 'The custom container image selects its Function host runtime.')
                return 'NOT_APPLICABLE', {'observed': text + ' The classic appsetting update-channel criterion does not apply.'}
            if hosting != 'classic' or settings is None: raise ValueError()
            channel = settings['channel']
            if channel in ('unresolved','masked','reference'): raise ValueError()
            observed = {
                'major4_automatic': 'The Function declares the automatic major4 runtime update channel.',
                'legacy_automatic': 'The Function declares an automatic update channel for a retired runtime major.',
                'major4_pin': 'The Function pins a major4 runtime build instead of declaring its automatic update channel.',
                'legacy_pin': 'The Function pins a build from a retired runtime major.',
                'absent': 'The Function does not declare the automatic major4 runtime update channel.'}[channel]
            return ('PASS' if channel == 'major4_automatic' else 'FAIL'), {
                'observed': observed + ' The resolved host build was not tested.', 'channel': channel,
                'coverage': 'selected_function_configuration_only'}
        if settings is None: raise ValueError()
        values = [settings['connection_string'], settings['instrumentation_key']]
        if any(v in ('masked','reference') for v in values): raise ValueError()
        declared = 'literal' in values
        text = ('The Function declares a nonempty Application Insights setting.' if declared
                else 'The Function has no nonempty Application Insights setting.')
        return ('PASS' if declared else 'FAIL'), {'observed': text + ' Telemetry delivery and destination validity were not tested.',
            'telemetry_setting_declared': declared, 'coverage': 'selected_function_configuration_only'}
    except (KeyError, ValueError, TypeError, AttributeError, IndexError):
        text = ('The selected Function telemetry declaration could not be established.' if check == source.TELEMETRY
                else 'The selected Function runtime update-channel declaration could not be established.')
        return 'UNKNOWN', {'observed': text, 'coverage': 'incomplete_selected_function_configuration'}

def _pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise Incomplete('duplicate_native_field')
        result[key] = value
    return result

def _remaining(reader, state):
    reader.check_cancelled()
    left = state['deadline'] - time.monotonic()
    if left <= 0:
        raise Incomplete('deadline_exceeded')
    return min(left, 10)

def _claims(token):
    try:
        segment = token.split(".")[1]
        value = json.loads(base64.urlsafe_b64decode(segment + "=" * (-len(segment) % 4)))
        return value if isinstance(value, dict) else {}
    except (ValueError, IndexError, TypeError):
        return {}

def _metadata_only(value, secret=False):
    if isinstance(value, list):
        return [_metadata_only(item, secret) for item in value]
    if not isinstance(value, dict):
        return value
    result = {key: _metadata_only(item, secret) for key, item in value.items() if not (secret and key.lower() == "value") and key.lower() not in (
        "password", "adminpassword", "clientsecret", "accesstoken", "token",
        "connectionstring", "primarykey", "secondarykey", "privatekey", "customdata",
        "userdata", "protectedsettings", "protectedsettingsfromkeyvault", "appsettings",
        "machinekey", "decryptionkey", "validationkey", "sourceuri", "accesssas",
        "redisconfiguration", "tenantsettings", "apiproperties", "globalparameters",
        "migrationtoken", "secrettext", "webhookproperties", "storageaccountaccesskey", "storagecontainersaskey", "workspacekey", "securevalue", "pfx", "certificatepassword", "certificate", "privatekeybytes", "sharedaccesskey", "sharedaccesspolicykey", "accountkey", "storageaccountkey", "accesskey", "accesskeys", "sasuri", "sasurl", "sastoken", "secretvalue", "apikey", "apikeys", "administratorloginpassword", "settings")}
    if isinstance(value.get("environmentVariables"), list):
        result["environmentVariables"] = [{key: ("[REDACTED]" if data is not None else None) if key in ("value", "secureValue") else _metadata_only(data, secret) for key, data in variable.items() if key in ("name", "value", "secureValue")} if isinstance(variable, dict) else _metadata_only(variable, secret) for variable in value["environmentVariables"]]
    for field in ("passwordCredentials", "keyCredentials"):
        if isinstance(value.get(field), list):
            result[field] = [{key: data for key, data in credential.items() if key in ("keyId", "startDateTime", "endDateTime")} if isinstance(credential, dict) else _metadata_only(credential, secret) for credential in value[field]]
    credential_names = {"token", "apitoken", "apikey", "accesskey", "accesskeyid",
                        "secretaccesskey", "accesskeysecret", "clientsecret", "secret",
                        "password", "passwd", "privatekey", "accesstoken", "refreshtoken",
                        "bearertoken", "authorization", "connectionstring", "sastoken",
                        "credential", "credentials", "workspacekey"}
    parameter_name = value.get("name") or value.get("parameterName")
    if isinstance(parameter_name, str) and re.sub(r"[^a-z0-9]", "", parameter_name.lower()) in credential_names | {"primarykey", "secondarykey", "sharedaccesskey", "sharedaccesspolicykey", "storageaccountkey", "storageaccountaccesskey", "storagecontainersaskey"}:
        if "value" in value:
            result["value"] = "[REDACTED]" if value["value"] is not None else None
    for field, tags in value.items():
        if field.lower() not in ("tags", "labels") or not isinstance(tags, dict):
            continue
        safe_tags, redacted = {}, []
        for key, item in tags.items():
            normalized = re.sub(r"[^a-z0-9]", "", key.lower())
            if normalized in credential_names:
                safe_tags[key] = "[REDACTED]"
                redacted.append({"key": key, "status": "redacted"})
            else:
                safe_tags[key] = _metadata_only(item, secret)
        result[field] = safe_tags
        if redacted:
            result.setdefault("_redacted_metadata", {})[field] = redacted
    return result

def _read(self, job):
    kind, scope, service, fetch = job
    items = {}
    status, error = "collected", None
    scoped_types = set(ENDPOINTS) | {"key_vault_certificate", "resource_graph", "subnet", "vnet_peering", "diagnostic_setting", "storage_service", "sql_database", "sql_firewall_rule", "sql_audit", "sql_security", "secret_metadata", "dns_record", "private_dns_link", "app_service_config", "app_service_identity_detail", "sql_tde", "managed_identity_federated_credential", "key_metadata", "key_rotation_policy", "key_vault_certificate_policy", "sql_vulnerability_assessment", "sql_encryption_protector", "storage_container", "storage_encryption_scope"}
    try:
        self.check_cancelled()
        for page in fetch():
            self.check_cancelled()
            if not isinstance(page, list) or any(not isinstance(item, dict) for item in page):
                raise ValueError("malformed page")
            for item in page:
                identifier = item.get("id")
                if not isinstance(identifier, str) or not identifier:
                    raise ValueError("missing authoritative resource identity")
                if service != "kubernetes" and kind in scoped_types and scope.startswith("/subscriptions/") and not _policy_assignment_scope_allowed(kind, scope, identifier):
                    raise ValueError("resource outside selected ARM scope")
                normalized = identifier.lower() if service != "kubernetes" else identifier
                if normalized not in items and self.budget.max_items is not None and len(items) >= self.budget.max_items:
                    raise AzureReadError("resource_limit")
                projected = item if service == "kubernetes" else _metadata_only(item, kind == "secret_metadata" or str(item.get("type", "")).lower().endswith("/secrets"))
                if kind == "app_service":
                    projected = azure_functions_runtime_native.safe_site_inventory(projected)
                if kind in azure_alert_routing_native.CONTRACTS:
                    try:
                        projected = azure_alert_routing_native.project(kind, scope, projected, ENDPOINTS[kind][1])
                    except ValueError:
                        # Preserve native metadata for other controls while
                        # making unavailable routing interpretation explicit.
                        projected = {**projected, '_routing_provenance': {
                            'status': 'unavailable', 'code': 'native_routing_unresolved'}}
                if kind in ('storage_account', 'embedded_blobContainers', 'embedded_encryptionScopes') and normalized in items:
                    raise ValueError('duplicate native storage identity')
                if kind == 'subscription' and normalized in items and items[normalized] != projected:
                    raise ValueError('conflicting subscription tenant identity')
                if kind in ('aks_cluster', 'embedded_localUsers', 'embedded_extensions', 'embedded_backupShortTermRetentionPolicies', 'embedded_eventSubscriptions') and normalized in items:
                    raise ValueError('duplicate native child identity')
                if kind in ('conditional_access_policy', 'named_location') and normalized in items:
                    raise ValueError('duplicate native Conditional Access policy or location identity')
                if kind in azure_alert_routing_native.CONTRACTS and normalized in items:
                    raise ValueError('duplicate native alert identity')
                if kind == 'security_assessment' and normalized in items and items[normalized] != projected:
                    raise ValueError('conflicting native security assessment identity')
                if kind == 'embedded_guestConfigurationAssignments' and normalized in items and items[normalized] != projected:
                    raise ValueError('conflicting guest assignment identity')
                if kind == 'embedded_backupProtectedItems' and normalized in items and items[normalized] != projected:
                    raise ValueError('conflicting backup protected item identity')
                if kind == 'policy_assignment' and normalized in items:
                    raise ValueError('duplicate native policy assignment identity')
                items.setdefault(normalized, projected)
    except Exception as exc:
        status, error = _safe_error(exc)
        if items or getattr(exc, "code", "") in ("resource_limit", "page_limit", "call_limit", "graph_truncated", "scope_limit", "collection_cancelled"):
            status = "partial"
    if status == "collected" and not items:
        status = "empty"
    result = {"type": kind, "scope": scope, "service": service, "status": status, "items": list(items.values())}
    if error:
        result["error"] = error
    self.progress(scope=scope, settled=result)
    return result

def final_snapshot(reader,snapshot):
    attributes=('configuration_secret_redactions','storage_source_secret_redactions','devops_selected_redactions',
                'app_setting_secret_redactions','acr_image_secret_redactions')
    values=set();overflow=getattr(reader,'storage_source_secret_overflow',False)
    try:
        # Merge every ledger before any scrub; later finalizers must not
        # reintroduce a metadata value already detected in another surface.
        for name in ('configuration_secret_metadata','storage_source_secret_metadata','devops_selected_metadata'):
            snapshot.setdefault('metadata',{}).update(getattr(reader,name,{}))
        for name in attributes:
            existing=getattr(reader,name,set())
            if (len(existing)>MAX_UNION_VALUES or any(len(v.encode())>storage.MAX_REDACTION_VALUE_BYTES for v in existing)):
                overflow=True;continue
            values.update(existing)
            if len(values)>MAX_UNION_VALUES or sum(len(v.encode()) for v in values)>storage.MAX_REDACTION_TOTAL:
                overflow=True;values.clear()
        if not hasattr(reader,'storage_source_secret_metadata'):reader.storage_source_secret_metadata={}
        snapshot=devops.final_snapshot(reader,snapshot)
        snapshot=arm.final_snapshot(reader,snapshot)
        # Other finalizers clear their own sets, so preserve the union in the
        # bounded final scrub, including when Storage itself was not selected.
        getattr(reader,'storage_source_secret_redactions',set()).clear()
        reader.storage_source_secret_redactions=values
        reader.storage_source_secret_overflow=overflow
        return storage.final_snapshot(reader,snapshot)
    finally:
        values.clear()
        for name in attributes:getattr(reader,name,set()).clear()

